begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('70000000-0000-0000-0000-000000000001','collab-owner@example.test'),('70000000-0000-0000-0000-000000000002','collab-member@example.test');
insert into public.profiles(id,name,username) values('70000000-0000-0000-0000-000000000001','Owner','collab_test_owner'),('70000000-0000-0000-0000-000000000002','Member','collab_test_member');
insert into public.workspaces(id,name,owner_id) values('70000000-0000-0000-0000-000000000010','Collaboration','70000000-0000-0000-0000-000000000001');
insert into public.workspace_members(workspace_id,user_id) values('70000000-0000-0000-0000-000000000010','70000000-0000-0000-0000-000000000002');
insert into public.boards(id,workspace_id,name) values('70000000-0000-0000-0000-000000000020','70000000-0000-0000-0000-000000000010','Test');
insert into public.tasks(id,workspace_id,board_id,column_id,title)
 select '70000000-0000-0000-0000-000000000030',workspace_id,board_id,id,'Task' from public.columns where board_id='70000000-0000-0000-0000-000000000020' and name='TODO';
select ok(not has_function_privilege('authenticated','public.claim_storage_cleanup()','EXECUTE'),'cleanup claims denied to clients');
select ok(not has_function_privilege('authenticated','public.complete_storage_cleanup(text,uuid)','EXECUTE'),'cleanup acknowledgements denied to clients');
select ok(not has_table_privilege('authenticated','private.storage_cleanup','SELECT'),'cleanup paths are private');
select ok(not has_column_privilege('authenticated','public.attachments','upload_state','UPDATE'),'clients cannot forge ready status');
select ok(not has_column_privilege('authenticated','public.attachments','storage_path','INSERT'),'clients cannot forge file metadata');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-0000-0000-000000000002',true);
select set_config('test.attachment',to_jsonb(public.reserve_attachment('70000000-0000-0000-0000-000000000030','brief.txt','text/plain',10))::text,true);
select is(current_setting('test.attachment')::jsonb->>'upload_state','pending','new reservation is incomplete');
select ok(private.can_upload_attachment(current_setting('test.attachment')::jsonb->>'storage_path'),'uploader may upload to reserved path');
select throws_ok($$select public.finalize_attachment((current_setting('test.attachment')::jsonb->>'id')::uuid)$$,'22023',null,'cannot finalize missing bytes');
select throws_ok($$select public.reserve_attachment('70000000-0000-0000-0000-000000000030','huge.pdf','application/pdf',10485761)$$,'23514',null,'server rejects oversize reservation');
select throws_ok($$select public.reserve_attachment('70000000-0000-0000-0000-000000000030','bad.html','text/html',10)$$,'23514',null,'server rejects unsupported MIME');
select set_config('request.jwt.claim.sub','70000000-0000-0000-0000-000000000001',true);
select ok(not private.can_upload_attachment(current_setting('test.attachment')::jsonb->>'storage_path'),'another member cannot upload into reservation');
reset role;
insert into storage.objects(bucket_id,name,metadata) values('task-attachments',current_setting('test.attachment')::jsonb->>'storage_path','{"size":9,"mimetype":"text/plain"}');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.finalize_attachment((current_setting('test.attachment')::jsonb->>'id')::uuid)$$,'22023',null,'actual object size must match');
reset role;
update storage.objects set metadata='{"size":10,"mimetype":"text/plain"}' where name=current_setting('test.attachment')::jsonb->>'storage_path';
set local role authenticated;
select lives_ok($$select public.finalize_attachment((current_setting('test.attachment')::jsonb->>'id')::uuid)$$,'valid object finalized');
select lives_ok($$select public.finalize_attachment((current_setting('test.attachment')::jsonb->>'id')::uuid)$$,'finalize retry is idempotent');
select is((select count(*) from public.activities where task_id='70000000-0000-0000-0000-000000000030' and action='attachment.added'),1::bigint,'finalize retry does not duplicate history');
select ok(not private.can_upload_attachment(current_setting('test.attachment')::jsonb->>'storage_path'),'ready file cannot be overwritten');
insert into public.comments(task_id,workspace_id,board_id,body) values('70000000-0000-0000-0000-000000000030','70000000-0000-0000-0000-000000000010','70000000-0000-0000-0000-000000000020','Private comment body');
select ok(not exists(select 1 from public.activities where workspace_id='70000000-0000-0000-0000-000000000010' and metadata::text like '%Private comment body%'),'history does not copy comment bodies');
delete from public.attachments where id=(current_setting('test.attachment')::jsonb->>'id')::uuid;
select ok(not private.can_read_attachment(current_setting('test.attachment')::jsonb->>'storage_path'),'metadata deletion immediately revokes file reads');
reset role;
select ok(exists(select 1 from private.storage_cleanup where path=current_setting('test.attachment')::jsonb->>'storage_path'),'deletion atomically queues physical cleanup');
delete from public.workspaces where id='70000000-0000-0000-0000-000000000010';
select ok(exists(select 1 from private.storage_cleanup where path=current_setting('test.attachment')::jsonb->>'storage_path'),'cleanup survives workspace cascade');
select is((select count(*) from public.activities where workspace_id='70000000-0000-0000-0000-000000000010'),0::bigint,'workspace cascade removes history without FK errors');
select * from finish();
rollback;
